package com.ashokmart;
import com.ashokmart.filter.CsrfFilter; import com.ashokmart.util.ValidationUtil; import org.junit.jupiter.api.Test; import javax.servlet.FilterChain; import javax.servlet.http.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class SecurityHardeningTest {
 @Test void validationUtilityRejectsUnsafeBoundaries(){assertEquals(1,ValidationUtil.page(null));assertEquals(20,ValidationUtil.pageSize(null));assertEquals(100,ValidationUtil.pageSize("100"));assertThrows(IllegalArgumentException.class,()->ValidationUtil.pageSize("101"));assertThrows(IllegalArgumentException.class,()->ValidationUtil.positiveQuantity("0"));assertThrows(IllegalArgumentException.class,()->ValidationUtil.rating("6"));assertEquals("Name",ValidationUtil.required(" Name ","Name",20));}
 @Test void csrfFilterRejectsMissingTokenAndAcceptsSessionToken()throws Exception{CsrfFilter filter=new CsrfFilter();HttpServletRequest request=mock(HttpServletRequest.class);HttpServletResponse response=mock(HttpServletResponse.class);FilterChain chain=mock(FilterChain.class);HttpSession session=mock(HttpSession.class);when(request.getMethod()).thenReturn("POST");when(request.getSession(false)).thenReturn(session);when(session.getAttribute(CsrfFilter.TOKEN_ATTRIBUTE)).thenReturn("expected");when(request.getParameter(CsrfFilter.TOKEN_PARAMETER)).thenReturn("wrong");filter.doFilter(request,response,chain);verify(response).sendError(HttpServletResponse.SC_FORBIDDEN,"The request could not be verified.");verifyNoInteractions(chain);reset(response,chain);when(request.getParameter(CsrfFilter.TOKEN_PARAMETER)).thenReturn("expected");filter.doFilter(request,response,chain);verify(chain).doFilter(request,response);verify(response,never()).sendError(anyInt(),anyString());}
}
